  test('Parsing invalid syntax should produce a tree with error nodes.', () async {
    final config = await createProcessConfigFromJson(json: '{"language":"javascript"}');
    final result = await TreeSitterLanguagePackBridge.process('function function function @@@ %%%', config: config);
    expect(result, isNotNull);
  });

  test('Loading a nonexistent language should produce an error.', () async {
    await expectLater(() async {
      final config = await createProcessConfigFromJson(json: '{"language":"nonexistent_xyz"}');
      return TreeSitterLanguagePackBridge.process('', config: config);
    }(), throwsA(anything));
  });

  test('Process empty source code succeeds with zero metrics', () async {
    final config = await createProcessConfigFromJson(json: '{"language":"python"}');
    final result = await TreeSitterLanguagePackBridge.process('', config: config);
    expect(result.metrics.totalLines, equals(0));
  });

  test('process() returns error with empty language name', () async {
    await expectLater(() async {
      final config = await createProcessConfigFromJson(json: '{"language":""}');
      return TreeSitterLanguagePackBridge.process('x = 1', config: config);
    }(), throwsA(anything));
  });

  test('process() returns error when config language is unknown', () async {
    await expectLater(() async {
      final config = await createProcessConfigFromJson(json: '{"language":"nonexistent_xyz"}');
      return TreeSitterLanguagePackBridge.process('x = 1', config: config);
    }(), throwsA(anything));
  });

